Let me write doClearAll:

```js
// 清空所有内容：scope 0=全部（本地+云端） 1=仅本地 2=仅云端
doClearAll () {
  var that = this
  var scope = that.scope
  utils.storageGet('todo_items').then(function (d1) {
    var items = []
    if (d1) { try { items = JSON.parse(d1) } catch (e) { items = [] } }
    utils.storageGet('todo_notes').then(function (d2) {
      var notes = []
      if (d2) { try { notes = JSON.parse(d2) } catch (e) { notes = [] } }
      var todoCids = []
      var noteCids = []
      for (var i = 0; i < items.length; i++) {
        if (items[i] && items[i].cloudId) { todoCids.push(items[i].cloudId) }
      }
      for (var j = 0; j < notes.length; j++) {
        if (notes[j] && notes[j].cloudId) { noteCids.push(notes[j].cloudId) }
      }
      var finish = function (msg) {
        utils.toast(msg)
        router.back()
      }
      // 仅删除云端：本地保留标 localOnly，云端进待删
      if (scope === 2) {
        for (var a = 0; a < items.length; a++) {
          if (items[a] && items[a].cloudId) { items[a].localOnly = true; items[a].cloudId = null }
        }
        for (var b = 0; b < notes.length; b++) {
          if (notes[b] && notes[b].cloudId) { notes[b].localOnly = true; notes[b].cloudId = null }
        }
        // queue deletes...
        queueAll(todoCids, noteCids, function () {
          utils.storageSet('todo_items', JSON.stringify(items)).then(function () {
            utils.storageSet('todo_notes', JSON.stringify(notes)).then(function () { finish('已清空云端') })
          })
        })
        return
      }
      // 仅删除本地 / 全部：本地清空
      var writeEmpty = function () {
        utils.storageSet('todo_items', '[]').then(function () {
          utils.storageSet('todo_notes', '[]').then(function () {
            finish(scope === 1 ? '已清空本地' : '已清空所有内容')
          })
        })
      }
      if (scope === 1) { writeEmpty(); return }
      // scope 0: queue cloud deletes first
      queueAll(todoCids, noteCids, writeEmpty)
    })
  })
}
```

Where queueAll appends cids to todo_pending_delete and todo_pending_delete_notes.

